import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/**
 * Column helpers shared by every table.
 * - UUID primary keys generated by PostgreSQL (gen_random_uuid, pgcrypto / core in PG13+).
 * - timestamptz everywhere; the app renders Europe/Paris explicitly.
 */
export const id = () => uuid("id").primaryKey().defaultRandom();

export const createdAt = () => timestamp("created_at", { withTimezone: true, mode: "date" }).notNull().defaultNow();

export const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true, mode: "date" })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const timestamps = () => ({
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/** Soft-delete marker for entities with a retention policy (null = live). */
export const deletedAt = () => timestamp("deleted_at", { withTimezone: true, mode: "date" });

export const nowSql = sql`now()`;
